(6421246, 952227, 49109, '<td valign="top">well composed, almost perfectly focused. the gray area bottom left bothers me a bit, but that''s a minor flaw in "minimal"</td>', 'well composed, almost perfectly focused. the gray area bottom left bothers me a bit, but that''s a minor flaw in "minimal"', '2011-05-22 12:04:50.000000', NULL, 1),
