INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6421613, 952227, 66384, '<td valign="top">Well done!</td>', 'Well done!', '2011-05-22 20:22:47.000000', NULL, 1),
(6421614, 952025, 66384, '<td valign="top">Great idea, using the white spoons to achieve the curves and gradients in the background. Lovely image.</td>', 'Great idea, using the white spoons to achieve the curves and gradients in the background. Lovely image.', '2011-05-22 20:25:29.000000', NULL, 1),
(6421615, 951400, 66384, '<td valign="top">Love this image! Don''t think it quite fits the challenge, since the background is not white.</td>', 'Love this image! Don''t think it quite fits the challenge, since the background is not white.', '2011-05-22 20:28:23.000000', NULL, 1),
(6421616, 951507, 66384, '<td valign="top">I think I would like this better with a little more light on the cards. Still, nicely done.</td>', 'I think I would like this better with a little more light on the cards. Still, nicely done.', '2011-05-22 20:30:52.000000', NULL, 1),
